script:
lines = text(repo.read("logs/service.log")).lines()
out = []
for i, l in enumerate(lines):
    if "ALERT" in l:
        for j in range(max(0, i - 1), min(len(lines), i + 2)):
            out.append("%d: %s" % (j + 1, lines[j]))
return "\n".join(out)
